    g = _to_scalar(gamma, "gamma")
    u = _to_scalar(rho_clip, "rho_clip")

    u = _to_scalar(rho_clip, "rho_clip")
    clip_c = _to_scalar(c_clip, "c_clip")
    if g < 0.0 or g > 1.0:
